-- ── archive everything else (never delete) ───────────────────────────────────
update crop set archived_at = now(), archived_reason = 'Not in the 0.7.57 crop library', updated_at = now()
where archived_at is null
  and lower(name) not in ('tomato cherry indeterminate', 'tomato round indeterminate', 'cucumber mini', 'cucumber english', 'climbing green bean', 'tomato determinate', 'bell pepper red', 'bell pepper yellow', 'chilli', 'eggplant', 'courgette', 'bush green bean', 'strawberry albion', 'strawberry chandler', 'butterhead lettuce', 'iceberg lettuce', 'romaine lettuce', 'leaf lettuce', 'frisée', 'escarole', 'radicchio', 'baby spinach', 'pak choi', 'kale', 'swiss chard', 'rocket', 'mizuna', 'mâche', 'watercress', 'tatsoi', 'basil', 'coriander', 'flat parsley', 'curly parsley', 'dill', 'mint', 'chives', 'thyme', 'oregano', 'sage', 'pea microgreens', 'sunflower microgreens', 'radish microgreens', 'broccoli microgreens', 'mustard microgreens', 'kale microgreens', 'basil microgreens', 'coriander microgreens', 'beetroot microgreens', 'amaranth microgreens');

-- ── summary ──────────────────────────────────────────────────────────────────
select (select count(*) from crop where archived_at is null) as active_crops,
       (select count(*) from crop where archived_at is not null) as archived_crops,
       (select count(*) from sop where trigger_kind = 'crop_plan') as crop_plan_procedures,
       (select count(*) from crop_phase ph join crop_cycle cy on cy.id = ph.cycle_id join crop c on c.id = cy.crop_id
         where c.archived_at is null and not exists (select 1 from crop_phase_sop where phase_id = ph.id)) as phases_without_procedure;
commit;
